from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares_workers(xs: list[int], workers: int) -> int:
    """Sum of squares of xs, computing each square on a thread pool of
    `workers` threads. The result is identical for every worker count.
    Raises ValueError if workers < 1."""
    if workers < 1:
        raise ValueError("workers must be >= 1")
    with ThreadPoolExecutor(max_workers=workers) as ex:
        return sum(ex.map(square, xs))


def sum_squares(xs: list[int]) -> int:
    """Sum of the squares of every element of xs (0 for an empty list),
    with the squares computed in parallel on a thread pool."""
    return sum_squares_workers(xs, 4)


WORKER_COUNTS = [1, 2, 3, 4, 8, 32]


def test_sum_squares_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14
    assert sum_squares([]) == 0
    assert sum_squares([5]) == 25


def test_sum_squares_negatives() -> None:
    assert sum_squares([-3, 3]) == 18
    assert sum_squares([-1, -2, -3]) == 14


def test_sum_squares_big_ints() -> None:
    big = 10**20
    assert sum_squares([big, -big]) == 2 * big * big


@pytest.mark.parametrize("workers", WORKER_COUNTS)
def test_same_result_at_every_worker_count(workers: int) -> None:
    xs = list(range(-50, 51))
    expected = sum(square(x) for x in xs)
    assert sum_squares_workers(xs, workers) == expected


@pytest.mark.parametrize("workers", WORKER_COUNTS)
def test_workers_edge_inputs(workers: int) -> None:
    assert sum_squares_workers([], workers) == 0
    assert sum_squares_workers([7], workers) == 49
    assert sum_squares_workers([0, 0, 0], workers) == 0


def test_more_workers_than_items() -> None:
    assert sum_squares_workers([2, 3], 64) == 13


def test_results_agree_across_worker_counts_large() -> None:
    xs = [(i * 7919) % 1009 - 500 for i in range(2000)]
    results = {sum_squares_workers(xs, w) for w in WORKER_COUNTS}
    assert results == {sum(x * x for x in xs)}


def test_sum_squares_matches_workers_version() -> None:
    xs = [4, -5, 6, 0, 11]
    assert sum_squares(xs) == sum_squares_workers(xs, 4)


def test_input_not_mutated() -> None:
    xs = [3, 1, 2]
    sum_squares(xs)
    assert xs == [3, 1, 2]


@pytest.mark.parametrize("workers", [0, -1])
def test_invalid_workers(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares_workers([1, 2, 3], workers)


def test_pool_is_usable_directly() -> None:
    # sanity check that the reference computation via a pool matches
    xs = [1, 2, 3, 4]
    with ThreadPoolExecutor(max_workers=2) as ex:
        assert sum(ex.map(square, xs)) == sum_squares(xs)

